          <filter id="vl-duet-hand" x="-5%" y="-5%" width="110%" height="110%">
            <feTurbulence
              ref={noiseRef}
              type="fractalNoise"
              baseFrequency="0.012"
              numOctaves="2"
              seed="7"
              result="noise"
            />
            <feDisplacementMap
              in="SourceGraphic"
              in2="noise"
              scale={6}
              xChannelSelector="R"
              yChannelSelector="G"
            />
          </filter>
